/*
 * A test asserts by panicking, so the lints that forbid it are off here.
 */
#![allow(clippy::expect_used, clippy::panic, clippy::indexing_slicing)]

//! The settlement call, byte for byte what Foundry encodes.

use nox_shield_core::net::pool_errors::explain;
use nox_shield_core::wallet::settle_calldata;

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

fn n(v: u8) -> [u8; 32] {
    let mut w = [0u8; 32];
    w[31] = v;
    w
}

/// cast calldata "settleBatch(bytes,uint256[],(address,uint64,uint64,uint256,uint256,address[],uint256),bytes,bytes[])"
///   0xaabbcc "[1,...,12]" "(0x0,0,0,0,0,[],0)" 0x "[0x0102,0x03]"
const FOUNDRY: &str = "";

#[test]
fn settle_batch_matches_foundry() {
    let inputs: Vec<[u8; 32]> = (1..=12).map(n).collect();
    let got = settle_calldata(&[0xaa, 0xbb, 0xcc], &inputs, &[vec![0x01, 0x02], vec![0x03]]);
    assert_eq!(hex(&got), FOUNDRY);
}

#[test]
fn a_revert_reads_as_a_sentence_or_its_selector() {
    // cast sig "NullifierAlreadySpent()"
    assert_eq!(explain(&[0xb1, 0x15, 0xd8, 0x57]), "One of these notes is already spent.");
    assert_eq!(explain(&[1, 2, 3, 4, 5]), "The pool refused the call (0x01020304).");
    assert_eq!(explain(&[]), "The pool refused the call without saying why.");
}
